using System;using System.IO;using System.Reflection;class Program{static int checks;static void Check(bool v,string why){checks++;if(!v)throw new Exception(why);}static void Main(){var t=Assembly.GetExecutingAssembly().GetType("ReleaseMetadataSync");Check(t!=null,"build must read release-version.json instead of stale resource");var m=t.GetMethod("Copy");var root=Path.Combine(AppContext.BaseDirectory,"fixtures");Directory.CreateDirectory(root);var source=Path.Combine(root,"release-version.json");var target=Path.Combine(root,"embedded.json");foreach(var version in new[]{"0.7.11","12.34.56"}){string json="{\"version\":\""+version+"\",\"date\":\"2026-11-02\",\"channel\":\"ea-full\"}";File.WriteAllText(source,json);Check((string)m.Invoke(null,new object[]{source,target})==version,"read current version");Check(File.ReadAllText(target)==json,"preserve canonical bytes");}File.WriteAllText(source,"{\"version\":\"wrong\"}");bool rejected=false;try{m.Invoke(null,new object[]{source,target});}catch(TargetInvocationException e){rejected=e.InnerException is FormatException;}Check(rejected,"invalid metadata rejects build");Check(File.ReadAllText(target).Contains("12.34.56"),"invalid source preserves prior output");Console.WriteLine("PASS "+checks+" release metadata behavior checks");}}